import { useState, useEffect, useCallback } from 'react';
import type { KnapsackInstance } from '@/types/games/knapsack';
import { getDailyChallenge } from '@/services/games/KnapsackService';

/**
 * Handles loading the daily Knapsack challenge from Firestore.
 * Challenges are pre-generated by a GitHub Actions cron job (scripts/generate-daily-challenge.js).
 */


export const useKnapsackDailyChallenge = (selectedDate: string) => {
    const [instance, setInstance] = useState<KnapsackInstance | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [notFound, setNotFound] = useState(false);
    const [loadedDate, setLoadedDate] = useState<string | null>(null);

    const loadChallenge = useCallback(async (dateStr: string) => {
        setIsLoading(true);
        setNotFound(false);
        setInstance(null);
        setLoadedDate(null);

        try {
            const loaded = await getDailyChallenge(dateStr);

            if (loaded) {
                setInstance(loaded);
                setLoadedDate(dateStr);
            } else {
                setNotFound(true);
            }
        } catch (error) {
            console.error("Error loading daily challenge:", error);
            setNotFound(true);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
            loadChallenge(selectedDate);
    }, [selectedDate, loadChallenge]);

    return {
        instance,
        isLoading,
        notFound,
        loadedDate,
        reload: () => loadChallenge(selectedDate),
    };
};
